window.getList = async function(path){
  const html = await (await fetch(path)).text();
  const m = html.match(/__BOOTSTRAP_URL__\s*=\s*["']([^"']+)["']/);
  if(!m) return {err:'no bootstrap url', head: html.slice(0,200)};
  const j = await (await fetch(m[1])).json();
  const p = j.page || j; const r = p.results || p.relatedMedia?.items || {};
  const arr = Array.isArray(r)?r:Object.values(r);
  return {total:p.total, pages:p.pages, items: arr.map(x=>({id:x.id, href:x.href, name:x.name, user:x.user&&x.user.username, dur:Math.round(x.duration), ai:x.isAiGenerated, cid:x.hasYoutubeContentId, lq:x.isLowQuality, g:(x.genres||[]).join('/'), m:(x.moods||[]).join('/'), mv:(x.movements||[]).join('/'), tags:(x.tags||[]).slice(0,6).join(','), dl:x.downloadCount, ec:x.isEditorsChoice}))};
};
