window.decodeWf = function(s, dur){
  const pts = s.trim().split('L').map(p=>p.trim().split(/\s+/).map(Number));
  const top=[]; let lastX=-1;
  for(const [x,y] of pts){ if(x<lastX) break; top.push([x,y]); lastX=x; }
  const N = top[top.length-1][0];
  const amp=[]; let j=0;
  for(let x=0;x<=N;x++){
    while(j<top.length-2 && top[j+1][0]<x) j++;
    const [x0,y0]=top[j], [x1,y1]=top[Math.min(j+1,top.length-1)];
    const y = x1===x0? y0 : y0+(y1-y0)*(x-x0)/(x1-x0);
    amp.push(15-y);
  }
  return {N, amp};
};
window.envStr = function(wf, dur, win){
  const {N,amp}=window.decodeWf(wf,dur); const per=N/dur; const out=[];
  for(let t=0;t<dur;t+=win){ const a=Math.floor(t*per), b=Math.min(amp.length,Math.floor((t+win)*per)+1); let s=0,c=0; for(let i=a;i<b;i++){s+=amp[i];c++;} out.push(c?(s/c):0); }
  return out;
};
window.inspectTrack = async function(id, href){
  const html = await (await fetch(href)).text();
  const m = html.match(/__BOOTSTRAP_URL__\s*=\s*["']([^"']+)["']/);
  if(!m) return {id, err:'nobs'};
  const j = await (await fetch(m[1])).json(); const mi=(j.page||j).mediaItem;
  let wfs=null; try{ wfs = await (await fetch('/music/'+id+'/waveform.json')).json(); }catch(e){}
  const dur=mi.duration; let env=null; if(wfs){ try{ env=window.envStr(wfs,dur,5).map(v=>Math.round(v).toString(16)).join(''); }catch(e){env='err'} }
  return {id, name:mi.name, user:mi.user.username, dur:Math.round(dur), ai:mi.isAiGenerated, cid:mi.hasYoutubeContentId, lq:mi.isLowQuality, ec:mi.isEditorsChoice, g:(mi.genres||[]).join('/'), m:(mi.moods||[]).join('/'), mv:(mi.movements||[]).join('/'), th:(mi.themes||[]).join('/'), tags:(mi.tags||[]).slice(0,8).join(','), dl:mi.downloadCount, plays:mi.viewCount, pub:mi.publishedDate, href, env};
};
const ids=[12327,145636,124014,117997,228100,167020,136110,375983,182513,145902];
const res=[]; for(const id of ids){ const c=window.cand[id]; try{ res.push(await window.inspectTrack(id,c.href)); }catch(e){ res.push({id,err:String(e)}); } await new Promise(r=>setTimeout(r,500)); }
window.res1=res; JSON.stringify(res)

